const roomObstacles=id=>id==='garden'?[{x:200,y:550,w:140,h:275},{x:1250,y:340,w:70,h:485}]:id==='harbor'?[{x:235,y:560,w:95,h:255},{x:1260,y:310,w:80,h:500}]:[{x:180,y:475,w:225,h:365},{x:1120,y:590,w:250,h:250},{x:220,y:305,w:215,h:87},{x:1120,y:305,w:220,h:95}];
const inside=(x,y,poly)=>{let ok=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const [xi,yi]=poly[i],[xj,yj]=poly[j];if((yi>y)!==(yj>y)&&x<(xj-xi)*(y-yi)/(yj-yi)+xi)ok=!ok;}return ok;};
const worldLand=[[100,325],[252,281],[467,271],[638,233],[906,233],[1079,316],[1390,307],[1440,764],[1240,848],[1056,834],[980,939],[663,971],[497,853],[323,803],[180,715],[208,596],[260,497],[215,440],[87,424]];
export function makeScene(worlds,level='world',worldId=null,nodeId=null){const w=worlds.find(x=>x.id===worldId),n=w?.nodes.find(x=>x.id===nodeId);if(level==='world'||!w){return {id:'world',level:'world',title:'虚构任务小岛',width:1536,height:1024,background:'assets/island.png',spawn:{x:761,y:598},world:null,node:null,obstacles:[{x:137,y:15,w:287,h:258},{x:650,y:32,w:271,h:222},{x:1088,y:15,w:338,h:294},{x:105,y:455,w:229,h:205},{x:583,y:619,w:400,h:210},{x:1120,y:422,w:329,h:285},{x:701,y:427,w:144,h:99}],canWalk:(x,y,r)=>[[x-r,y],[x+r,y],[x,y-r],[x,y+r]].every(p=>inside(...p,worldLand)),entities:[...worlds.map(x=>({id:'portal-'+x.id,type:'portal',x:WORLD_PORTALS[x.id][0],y:WORLD_PORTALS[x.id][1],worldId:x.id,label:x.name,number:x.number,state:x.state,subtitle:x.label})),{id:'guide',type:'guide',x:842,y:598,label:'领路员',role:'探索向导',state:'planned'}],theme:THEMES.harbor};}
if(level==='region'||!n){let coords=w.nodes.length===5?[[458,396],[768,355],[1078,396],[465,700],[1075,700]]:w.nodes.length===4?[[468,470],[768,365],[768,714],[1070,470]]:[[462,421],[768,355],[1074,421]];return {id:w.id,level:'region',title:w.name,width:1536,height:1024,world:w,node:null,background:w.id==='garden'?'assets/studio.png':w.id==='harbor'?'assets/workshop.png':'assets/archive.png',theme:THEMES[w.id],spawn:{x:768,y:790},canWalk:(x,y,r)=>x-r>=235&&x+r<=1302&&y-r>=305&&y+r<=843,obstacles:roomObstacles(w.id),entities:[...w.nodes.map((n,i)=>({id:'stage-'+n.id,type:'stage',x:coords[i][0],y:coords[i][1],nodeId:n.id,worldId:w.id,number:n.number,label:n.title,state:n.state,subtitle:n.short})),{id:'npc-'+w.id,type:'npc',x:767,y:577,label:w.npc?.name||'项目负责人岗位',role:w.npc?.role||w.subject,worldId:w.id,state:w.state},{id:'exit',type:'exit',x:767,y:832,label:'返回世界'}]};}
const index=w.nodes.indexOf(n),spots=w.id==='harbor'?[[490,410],[795,410],[424,684],[1080,600]]:w.id==='garden'?[[470,425],[760,405],[1120,525],[465,690],[1020,690]]:[[490,410],[790,410],[1080,470],[490,690],[1040,690]];const focus=spots[index%spots.length];
return {id:n.id,level:'stage',title:n.station||n.title,width:1536,height:1024,world:w,node:n,theme:THEMES[w.id],background:w.id==='garden'?'assets/studio.png':w.id==='harbor'?'assets/workshop.png':'assets/archive.png',spawn:{x:focus[0],y:focus[1]+65},canWalk:(x,y,r)=>x-r>=285&&x+r<=1250&&y-r>=325&&y+r<=833,obstacles:roomObstacles(w.id),entities:[{id:n.id+'-progress',type:'topic',topic:'progress',x:470,y:372,label:'进度记录',subtitle:'已知事实与阶段边界',prop:'existing'},{id:n.id+'-results',type:'topic',topic:'results',x:1070,y:372,label:'成果陈列',subtitle:'交付物与验收口径',prop:'existing'},{id:n.id+'-blockers',type:'topic',topic:'blockers',x:370,y:665,label:'条件检查',subtitle:'缺口与可信边界',prop:'existing'},{id:n.id+'-nextSteps',type:'topic',topic:'nextSteps',x:1170,y:665,label:'下一步路线',subtitle:'有边界的续接方法',prop:'existing'},{id:'npc-'+n.id,type:'npc',x:770,y:557,label:w.npc?.name||'项目负责人岗位',role:w.npc?.role||w.subject,state:w.state},{id:'evidence-'+n.id,type:'evidence',x:770,y:380,label:'来源档案',subtitle:'时间、依据与证据状态',prop:'existing'},{id:'exit',type:'exit',x:770,y:825,label:'返回项目大厅'}]};}

export function regionPortals(){return WORLD_PORTALS;}
